'use strict';

/*
 * discover_onlyy_pools.js — READ-ONLY Mainnet DLMM pool discovery for
 * `collect_fee_mode = 1` (OnlyY) pools with the supported Spot function type.
 *
 * Motivation: QUOTE_PARITY_REPORT.md §4.4 records that the OnlyY (mode 1)
 * fee-mode coverage of the DLMM differential is generated by overriding
 * `collectFeeMode` on captured in-memory state of InputOnly pools. This script
 * discovers pools whose deployed state genuinely has bit
 * `LbPair.staticParameters.collectFee_mode = 1` (account offset 36 per the
 * verified v0.12.0 layout) so the harness can capture a real OnlyY pool.
 *
 * REDUCED-STATE SCAN via getProgramAccounts + dataSlice:
 *   offset 35 function_type (u8)     — engine supports Spot (0) only
 *   offset 36 collect_fee_mode (u8)  — filter for OnlyY (1)
 *   offset 76 active_id (i32)
 *   offset 80 bin_step (u16)
 *   offset 82 status (u8)
 *   offset 88..152 mint_x, mint_y
 *   offset 152..216 reserve_x, reserve_y
 * Then ranks candidates by token-account balance read at offset 64..72 of the
 * reserve (SPL Token) accounts.
 *
 * Never signs or submits anything; pure getProgramAccounts/getMultipleAccounts.
 */

const fs = require('fs');
const crypto = require('crypto');
const path = require('path');
const bs58 = require('bs58').default;
const { Connection, PublicKey } = require('@solana/web3.js');

const RPC_URL = process.env.RPC_URL || 'https://api.mainnet-beta.solana.com';
const DLMM_PROGRAM_ID = new PublicKey(
  'LBUZKhRxPF3XUpBCjp4YzTKgLccjZhTSDM9YuVaPwxo'
);
const SPL_TOKEN_PROGRAM = new PublicKey(
  'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA'
);
const WSOL = new PublicKey('So11111111111111111111111111111111111111112');
const USDC = new PublicKey('EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v');

const KNOWN_QUOTE_MINTS = new Map([
  ['So11111111111111111111111111111111111111112', 'WSOL'],
  ['EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', 'USDC'],
  ['Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', 'USDT'],
]);

function connection() {
  return new Connection(RPC_URL, 'confirmed');
}

// Base58-encode the discriminator via a minimal decoder-free encoder using the
// bs58 dependency already used by the differential harness ecosystem.
function bs58EncodeDisc(buf) {
  return bs58.encode(buf);
}

// Anchor discriminator of the `LbPair` account type (first 8 bytes of
// sha256("account:LbPair")) — excludes Position / BinArray / PresetParameter
// accounts that would otherwise match the bare byte-offset filter.
function lbPairDiscriminator() {
  const hash = crypto.createHash('sha256');
  hash.update('account:LbPair', 'utf8');
  return Array.from(hash.digest().subarray(0, 8)).map((b) => b.toString(16).padStart(2, '0')).join('');
}

async function discover() {
  const c = connection();
  const disc = lbPairDiscriminator();
  // Base58-encoded 8-byte discriminator prefix, as required by memcmp.
  const discB58 = bs58EncodeDisc(Buffer.from(disc, 'hex'));
  console.log(`scanning DLMM program for LbPair(collect_fee_mode=1) pools (rpc=${RPC_URL})`);
  console.log(`discriminator hex=${disc} b58=${discB58}`);
  const res = await c.getProgramAccounts(DLMM_PROGRAM_ID, {
    filters: [
      {
        // LbPair Anchor discriminator (8 bytes at offset 0)
        memcmp: { offset: 0, bytes: discB58 },
      },
      {
        // raw account data[36] == 1 => CollectFeeMode::OnlyY
        memcmp: { offset: 36, bytes: '2' },
      },
    ],
    dataSlice: { offset: 0, length: 216 },
  });
  console.log(`onlyy accounts returned: ${res.length}`);

  const pools = [];
  const ftHist = {};
  for (const { pubkey, account } of res) {
    const data = account.data;
    if (data.length < 216) continue;
    const functionType = data[35];
    ftHist[functionType] = (ftHist[functionType] || 0) + 1;
    // 1 = LiquidityMining: quote-equivalent to classic pools (verified against
    // the SDK's isSupportLimitOrder / getLimitOrderLiquidity source.
    // 2 = LimitOrder: distinct fill semantics, not quotable here (fail-closed,
    // mirrored by crates/arb-dex/src/dlmm_validation.rs).
    if (functionType !== 0 && functionType !== 1) continue;
    const status = data[82];
    const activeId = data.readInt32LE(76);
    const binStep = data.readUInt16LE(80);
    const mintX = new PublicKey(data.subarray(88, 120)).toString();
    const mintY = new PublicKey(data.subarray(120, 152)).toString();
    const reserveX = new PublicKey(data.subarray(152, 184)).toString();
    const reserveY = new PublicKey(data.subarray(184, 216)).toString();
    pools.push({
      pubkey: pubkey.toString(),
      activeId,
      binStep,
      status,
      mintX,
      mintY,
      reserveX,
      reserveY,
    });
  }
  console.log(`function_type histogram (all OnlyY LbPairs): ${JSON.stringify(ftHist)}`);
  console.log(`onlyy + quoteable function_type pools (0/1): ${pools.length}`);

  // Rank by Y-side reserve balance (fees in OnlyY pools accrue in Y; Y is
  // usually the quote). Read token-account balance (offset 64..72) for all
  // reserve accounts of the candidate set.
  const reserveList = [];
  for (const p of pools) {
    reserveList.push(p.reserveX);
    reserveList.push(p.reserveY);
  }
  const balances = new Map();
  for (let i = 0; i < reserveList.length; i += 100) {
    const chunk = reserveList.slice(i, i + 100);
    const infos = await c.getMultipleAccountsInfo(chunk.map((k) => new PublicKey(k)));
    infos.forEach((info, j) => {
      if (!info || info.data.length < 72) return;
      balances.set(chunk[j].toString(), info.data.readBigUInt64LE(64));
    });
  }
  for (const p of pools) {
    p.balanceX = balances.get(p.reserveX)?.toString() ?? 'missing';
    p.balanceY = balances.get(p.reserveY)?.toString() ?? 'missing';
  }

  pools.sort((a, b) => {
    const ay = BigInt(a.balanceY === 'missing' ? '0' : a.balanceY);
    const by = BigInt(b.balanceY === 'missing' ? '0' : b.balanceY);
    return by >= ay ? (by === ay ? 0 : 1) : -1;
  });

  // Mint ownership check for the most liquid half of the pool set: quote
  // capture requires classic SPL Token mints on BOTH sides (Token-2022
  // transfer-fee mints are moved by the SDK oracle but rejected fail-closed
  // by the engine, so they are not a serving parity case).
  const mintSet = new Set();
  const checkDepth = pools.length;
  for (const p of pools) {
    mintSet.add(p.mintX);
    mintSet.add(p.mintY);
  }
  const mintList = [...mintSet];
  const mintOwner = new Map();
  for (let i = 0; i < mintList.length; i += 100) {
    const chunk = mintList.slice(i, i + 100);
    const infos = await c.getMultipleAccountsInfo(chunk.map((k) => new PublicKey(k)));
    infos.forEach((info, j) => {
      mintOwner.set(chunk[j], info ? info.owner.toString() : null);
    });
  }
  for (const p of pools) {
    const ox = mintOwner.get(p.mintX);
    const oy = mintOwner.get(p.mintY);
    p.mint_x_program = ox;
    p.mint_y_program = oy;
    p.both_classic_spl = ox === SPL_TOKEN_PROGRAM.toString() && oy === SPL_TOKEN_PROGRAM.toString();
  }
  pools.sort((a, b) => {
    if (a.both_classic_spl !== b.both_classic_spl) return a.both_classic_spl ? -1 : 1;
    const ay = BigInt(a.balanceY === 'missing' ? '0' : a.balanceY);
    const by = BigInt(b.balanceY === 'missing' ? '0' : b.balanceY);
    return by >= ay ? (by === ay ? 0 : 1) : -1;
  });

  const out = pools
    .slice(0, 60)
    .map((p) => ({
      ...p,
      y_is_sol: p.mintY === WSOL.toString(),
      y_is_usdc: p.mintY === USDC.toString(),
      quote_label_y: KNOWN_QUOTE_MINTS.get(p.mintY) || null,
      quote_label_x: KNOWN_QUOTE_MINTS.get(p.mintX) || null,
    }));
  console.log(JSON.stringify(out, null, 2));
  const outPath = process.env.DISCOVERY_OUT || '/tmp/dlmm_onlyy_discovery.json';
  fs.writeFileSync(outPath, JSON.stringify(out, null, 2) + '\n');
  console.log(`written: ${outPath}`);
}

discover().catch((e) => {
  console.error('discovery failed:', e);
  process.exit(1);
});
